public class METVendorRebateOffRemittanceCalcService extends METSysOperationService
{
    private METVendorRebateOffRemittanceCalcTaskContract contract;
    private guid queueId;
    Query userQuery;
    METVendorRebateOffRemittanceCalcContract mainContract;
}

