/// <summary>
/// constructs the field maps used to insert data from user query to temporary staging table.
/// </summary>
/// <param name = "_dataSourceId">Unique data source of the query data source</param>
/// <returns>Field map</returns>
private Map getFieldMap(int _dataSourceId, int _purchTableDS)
{
    Map fieldsMap = new Map(Types::String, Types::Container);

    fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, PackingSlipTransRecId), [_dataSourceId, fieldStr(VendPackingSlipTrans, RecId)]);
    fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, DefaultDimension), [_dataSourceId, fieldStr(VendPackingSlipTrans, DefaultDimension)]);
    fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, InventDimId), [_dataSourceId, fieldStr(VendPackingSlipTrans, InventDimId)]);
    fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, LineAmount), [_dataSourceId, fieldStr(VendPackingSlipTrans, ValueMST)]);
    fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, PurchId), [_dataSourceId, fieldStr(VendPackingSlipTrans, OrigPurchid)]);

    //fieldsMap.insert(fieldStr(METVendorRebateOffRemittanceCalcStagingTmp, CustomerReference), [_purchTableDS, fieldStr(PurchTable, PurchOrderFormNum)]);

    return fieldsMap;
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METReserveEventOrdersContract</c>
/// </param>
public void process(METVendorRebateOffRemittanceCalcContract _contract)
{
    mainContract = _contract;

    userQuery = new Query(_contract.getQuery());
    QueryBuildDataSource qbdrInventDim = userQuery.dataSourceTable(tableNum(InventDim));
    QueryBuildDataSource qbdrPackJour = userQuery.dataSourceTable(tableNum(VendPackingSlipJour));
    QueryBuildDataSource qbdrPurchTable = userQuery.dataSourceTable(tablenum(PurchTable));
    QueryBuildRange qbrCustomerReq; 

    dataContract = _contract as METVendorRebateOffRemittanceCalcContract;
    qbdrInventDim.addRange(fieldNum(InventDim, InventSiteId)).value(_contract.parmInventSite());

    qbdrPackJour.addRange(fieldNum(VendPackingSlipJour, DeliveryDate)).value('< ' + SysQuery::value(_contract.parmAsOfDate()));

    //this.initialise();
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables and initiates data staging.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Initializes process and stages data into table <t>METInternalTransferOrderQueue</t>.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    contract = dataContract as METVendorRebateOffRemittanceCalcTaskContract;
    queueId = newGuid();

    try
{
        ttsbegin;

        METVendorRebateOffRemittanceCalcStaging::cleanUpQueue();
        METVendorRebateSiteJournalStaging::cleanUpQueue();

        this.stageQueue();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        curext();
    }
}

/// <summary>
/// Stages orders to be processed based on user selection and .
/// </summary>
private void stageQueue()
{
    METVendorRebateOffRemittanceCalcStagingTmp metVendorRemittenceStageTmp;
    METVendorRebateOffRemittanceCalcStaging processQueue;
    SalesTable salesTable;
    METSalesTable metSalesTable;
    queryrun qr = new QueryRun(userQuery);
    DefaultDimensionView defaultDimension;
    InventDim inventDim;
    PurchTable PurchTable;

    userQuery.clearAllFields();

    QueryBuildDataSource qbdsVendPackingSlipTrans = userQuery.dataSourceName(tableStr(VendPackingSlipTrans));
    qbdsVendPackingSlipTrans.addSelectionField(fieldNum(VendPackingSlipTrans, RecId));
    qbdsVendPackingSlipTrans.addSelectionField(fieldNum(VendPackingSlipTrans, InventDimId));
    qbdsVendPackingSlipTrans.addSelectionField(fieldNum(VendPackingSlipTrans, DefaultDimension));
    qbdsVendPackingSlipTrans.addSelectionField(fieldNum(VendPackingSlipTrans, OrigPurchid));
    qbdsVendPackingSlipTrans.addSelectionField(fieldNum(VendPackingSlipTrans, ValueMST));

    //QueryBuildDataSource qbdsPurchTable = userQuery.dataSourceName(tableStr(PurchTable));
    //qbdsPurchTable.addSelectionField(fieldNum(PurchTable, PurchId));
    //qbdsPurchTable.addSelectionField(fieldNum(PurchTable, PurchOrderFormNum));

    Query::insert_recordset(metVendorRemittenceStageTmp, this.getFieldMap(qbdsVendPackingSlipTrans.uniqueId(), 0), userQuery);

    //Transfer the data from tmp table to Process queue with process Id.
    insert_recordset processQueue
        (ProcessId, PackingSlipTransRecId, InventDimId, DefaultDimension, LineAmount, SiteId, Department, CustomerReference, VendAccount)
        select queueId, PackingSlipTransRecId, InventDimId, DefaultDimension, LineAmount
        from metVendorRemittenceStageTmp
        join InventSiteId from inventDim 
            where inventDim.inventDimId == metVendorRemittenceStageTmp.InventDimId
        join DisplayValue from defaultDimension 
            where defaultDimension.DefaultDimension == metVendorRemittenceStageTmp.DefaultDimension
        && defaultDimension.Name == METConstants::Department
        join PurchOrderFormNum, InvoiceAccount from PurchTable 
        where PurchTable.PurchId == metVendorRemittenceStageTmp.PurchId
        && PurchTable.PurchStatus != PurchStatus::Invoiced
        && !(PurchTable.PurchOrderFormNum like 'HD*'
        || PurchTable.PurchOrderFormNum like 'VO*'
        || PurchTable.PurchOrderFormNum like 'VR*'
        || PurchTable.PurchOrderFormNum like 'SR*');

    MarkupAutoLine markupAutoLine;
    MarkupAutoTable markupAutoTable;
    METPurchGroup purchGroup;

    update_recordset processQueue
        setting ChargeCode = markupAutoLine.MarkupCode,
            ChargePercent = markupAutoLine.Value
            //ChargeAmount = processQueue.LineAmount * markupAutoLine.Value
        join markupAutoLine
        where markupAutoLine.TableRecId == markupAutoTable.RecId
        && markupAutoLine.TableTableId == markupAutoTable.TableId
        //&& markupAutoLine.FromDate <= mainContract.parmAsOfDate()
        //&& markupAutoLine.ToDate  >= mainContract.parmAsOfDate()
        join markupAutoTable
        where markupAutoTable.ModuleType == MarkupModuleType::Vend
        && markupAutoTable.AccountCode == TableGroupAll::Table
        && markupAutoTable.AccountRelation == processQueue.VendAccount
        && markupAutoTable.ModuleCategory == HeadingLine::Line
        exists join purchGroup
        where purchGroup.PurchGroupId == markupAutoLine.METPurchGroupId
        && purchGroup.InvoiceType == METPurchGroupInvoiceType::Warehouse;

    //Remove all packing slips which do not have a charge code mapping for the vendor or the purchase group invoice type is not warehouse.

    delete_from processQueue
        where processQueue.ChargeCode == ''
        && processQueue.ProcessId == queueId;

    METVendorRebateSiteJournalStaging siteStaging;

    insert_recordset siteStaging(ProcessId, SiteId)
        select ProcessId, SiteId from processQueue
        group by ProcessId, SiteId
        where processQueue.ProcessId == queueId;
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METVendorRebateOffRemittanceCalcTaskContract;
    contract.parmTopPickingProcessId(queueId);
    contract.parmAsOnDate(mainContract.parmAsOfDate());
    contract.parmReversalDate(mainContract.parmReversalDate());
    contract.parmGroupByChargeCode(mainContract.parmGroupByChargeCode());
    contract.parmGroupByDepartment(mainContract.parmGroupByDepartment());
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METVendorRebateOffRemittanceCalcTaskContract();
}
